<script type="text/javascript">
 /*$(document).ready(function () {*/
let bmvars = { PRIMEPLUS : [9,10,11], ADDRESSPROFSTATUS: [0,19,20,21,23] };
let memberId;
let redisValue;
let redisPIArray = (redisValue) ? redisValue.PI.split('|') : '';
let primeTag;
let primeonboardpopup;
let isToggledPrimeFirstTime;
let primetoggle;
let loginCount;
let memberType;
let validaysLeft;
let upsellingpromo;
let specialPriv;
let previousPageUrl = document.referrer;
let currentPageUrl = window.location.href;
var getMatchesCount;
let matchesCountUrl;
let ENCID;
let TOKENID;
let TIMECREATED;

 if (memberId){
  primeTag = toCheckPrime(redisPIArray[60],redisPIArray[37],redisPIArray[25],redisPIArray[61],redisPIArray[28],true);
  primeonboardpopup = getCookie('PRIMEONBOARDPOPUPSEARCH'); // prime onboard popup value
  primetoggle = getCookie('PRIMETOGGLE'); // prime toggle value
  loginCount = getCookie('LOGINCOUNT');  
  memberType = getCookie('MEMBERTYPE');
  validaysLeft = getCookie('VALIDAYSLEFT');
  // primeTag = getCookie('PRIMETAG'); // member's prime tag value
  upsellingpromo = getCookie('UPSELLPROMOVAL');  // need upselling promoval value
  specialPriv = getCookie('SPECIALPRIV');
  matchesCountUrl = getCookie('matchesCountUrl') + memberId;
  ENCID = getCookie('ENCID'); // ENCID value
  TOKENID = getCookie('TOKENID'); // TOKENID value
  TIMECREATED = getCookie('TIMECREATED'); // TIMECREATED value
  updatePrimeTab();
 }
function updatePrimeTab() {
  if(primeTag != '0' && primeTag != '') { //filter non eligible prime user
  if(primetoggle === '1'){ // for active prime toggle
    document.getElementById("tag-prime-active").style.display="block";
    document.getElementById("tag-normal-active").style.display="none";
    } else {  // for active regular toggle
      document.getElementById("tag-prime-active").style.display="none";
      document.getElementById("tag-normal-active").style.display="block";
  }
  updatePrimeOnboardPopup();
  }
}
function onClickPrimeTab(tabValue){  // click event for prime toggle
  if(primeTag != '0' && primeTag != '') { //filter non eligible prime user
    if (upsellingpromo !='0' &&  tabValue == '1' && primeTag == '1'  && parseInt(loginCount) % 3 == 0 && (memberType == 'R' || memberType == 'P') && (specialPriv == '0' || specialPriv == '1' || specialPriv == '2' || specialPriv == '6') && validaysLeft > '30') {
    setCookie('SEARCHPAGEURL', currentPageUrl);
    window.open(previousPageUrl + 'prime-upselling', '_self');  // document.referrer -- previous page url
      } else if (tabValue == '1' && primeTag != '1' && primeTag != '5') {
     setCookie('SEARCHPAGEURL', currentPageUrl); 
     window.open(previousPageUrl + 'prime', '_self');  // document.referrer -- previous page url
    } else {  // for PRIME and PRIMEPLUS MEMBER
    if(tabValue == '1'){
       setCookie('ISTOGGLEDPRIMEFIRSTTIMESEARCH', '1');
    }		 
     setCookie('PRIMETOGGLE', tabValue);
       primetoggle = tabValue;
     updatePrimeTab();
     getMatchesCount();
     }
     /*if(primeonboardpopup != '1') {
    onClickPrimeOnboardPopup();
     }*/
  }
 }
function updatePrimeOnboardPopup() {
  if(primeTag == 1 || primeTag == 5) { //filter non eligible prime user
  isToggledPrimeFirstTime = getCookie('ISTOGGLEDPRIMEFIRSTTIMESEARCH');
    if(primeonboardpopup === '1'){
    document.getElementsByClassName('primepopup')[0].style.display = 'none';
    document.getElementsByClassName('primepopup')[1].style.display = 'none';	
    } else if(primeonboardpopup !== '1' && isToggledPrimeFirstTime == '1') { 
    document.getElementsByClassName('primepopup')[0].style.display = 'block';	
    document.getElementsByClassName('primepopup')[1].style.display = 'block';
    setCookie('PRIMEONBOARDPOPUPSEARCH', '1');
    primeonboardpopup = '1';	
  }
  }
 }
 function onClickPrimeOnboardPopup(){  // click event for prime onboard popup
  setCookie('PRIMEONBOARDPOPUPSEARCH', '1');
  primeonboardpopup = '1';
    updatePrimeOnboardPopup();
}
function setCookie(cname, cvalue) {
  const hostname = window.location.hostname; // profile.tamilmatrimony.com
  let domain = hostname.split('.')[hostname.split('.').length-2]+'.'+ hostname.split('.')[hostname.split('.').length-1];
  document.cookie = cname + "=" + cvalue + ";domain=." + domain + ";path=/";
}
function getCookie(cname) {
   var name = cname + "=";
   var ca = document.cookie.split(';');
   for(var i = 0; i < ca.length; i++) {
      var c = ca[i];
      while (c.charAt(0) == ' ') {
        c = c.substring(1);
      }
      if (c.indexOf(name) == 0) {
        return c.substring(name.length, c.length);
      }
   }
   return "";
}

function empty(mixedVar) { 
  // *     example 3: empty([]);
  // *     returns 3: true
  var undef
  var key
  var i
  var len
  var emptyValues = [undef, null, false, 0, '', '0', 'undefined', undefined]
  for (i = 0, len = emptyValues.length; i < len; i++) {
    if (mixedVar === emptyValues[i]) {
      return true;
    }
  }
  if (typeof mixedVar === 'object') {
    for (key in mixedVar) {
      if (mixedVar.hasOwnProperty(key)) {
        return false;
      }
    }
    return true;
  }
  return false;
}

function in_array(needle, haystack, argStrict) {
  // *     example 2: in_array('outlets', {0: 'mobileshop', outlets: 'van', 1: 'Fieldstudy'});
  // *     returns 2: false
  var key = '',
    strict = !!argStrict;

  if (strict) {
    for (key in haystack) {
      if (haystack[key] === needle) {
        return true;
      }
    }
  } else {
    for (key in haystack) {
      if (haystack[key] == needle) {
        return true;
      }
    }
  }
  return false;
}
function toCheckPrime(verifiedFlag,photoAvailable,degree,Mempackage = 0,entrytype=0,piinfo = false){
    /* 45: "Trade School"
    46: "Diploma"
    82: "Polytechnic"
    94: "Others"
    47: "Higher Secondary School / High School" */
    let nonDegree = [45,46,82,94,47];
    if(piinfo) {
    let emptyOfDegree = empty(degree);
    // let in_arrayOfDegree = in_array(degree,nonDegree);
    if(!emptyOfDegree) {
      let emptyOfPhotoAvailable = empty(photoAvailable);
      let emptyOfVerifiedFlag = empty(verifiedFlag);
            if(!emptyOfPhotoAvailable && (photoAvailable == 'Y' || photoAvailable == 1) && !emptyOfVerifiedFlag && (verifiedFlag == 'Y' || verifiedFlag == 1)) {
                return (bmvars.PRIMEPLUS.includes(parseInt(Mempackage)) && (entrytype == 'P' || entrytype == 'R' || entrytype == 1)) ? 5 : 1;
            } else if ((emptyOfPhotoAvailable || photoAvailable == 'N' || photoAvailable == 0) && (emptyOfVerifiedFlag || verifiedFlag == 'N' || verifiedFlag == 0)) {
                return 4;
            } else if (emptyOfPhotoAvailable || photoAvailable == 'N' || photoAvailable == 0) {
                return 2;
            } else if (emptyOfVerifiedFlag || verifiedFlag == 'N' || verifiedFlag == 0) {
                return 3;
            } else if (!emptyOfVerifiedFlag && verifiedFlag == 2) {
                return 6; //idverification pending
            }
        } else {
            return 0;
        }
    } else {
        if(!empty(photoAvailable) && (photoAvailable == 'Y' || photoAvailable == 1) && !empty(degree) && !in_array(degree,nonDegree) && bmvars.ADDRESSPROFSTATUS.includes(parseInt(verifiedFlag))) {
            if(bmvars.PRIMEPLUS.includes(parseInt(Mempackage)) && (entrytype == 'P' || entrytype == 'R' || entrytype == 1)){
               return 2;
            }else{
               return 1;
            }
        } else {
            return 0;
        }
  }
}
