  params += '&ID=' + memberId;
  params += '&APPTYPE=300';  // 
  params += '&Lang=en';
  params += '&ENCID=' + ENCID;
  params += '&TOKENID=' + TOKENID;
  params += '&APIVERSION=1.2';
  params += '&TIMECREATED=' + TIMECREATED;
  params += '&UIVERSION=NEW';
  params += '&WEBPFLAG=1'; //

  getMatchesCount = function() {
    $.ajax({
      type: "POST",
      url: matchesCountUrl + params +  '&PRIMETAG=' + primetoggle,
      success: function(response){ 
      updateMatchesCount(response.ALLRESULTS);
      },
      error: function(error){

      }
     });
  }
  function updateMatchesCount(count){
    $("#matchcount").html(count);
    $("#allMatchcount").html('(' + count + ')');
  }
});
