    <script type="text/javascript">
           $( document ).ready(function() {
         //Set Default State of each portfolio piece
                $(".rp-soc-paging").show();
                $(".rp-soc-paging a:first").addClass("active");
                var imageWidth = $(".rp-soc-window").width();
                var imageSum = $(".rp-soc-image_reel img").size();
                var imageReelWidth = imageWidth * imageSum;
                $(".rp-soc-image_reel").css({'width' : imageReelWidth});
                rotate = function(){
                    var triggerID = $active.attr("rel") - 1;
                    var image_reelPosition = triggerID * imageWidth;
                    $(".rp-soc-paging a").removeClass('active'); 
                    $active.addClass('active'); 
                    $(".rp-soc-image_reel").animate({
                        left: -image_reelPosition
                    }, 500 );

                };

                rotateSwitch = function(){
                    play = setInterval(function(){ 
                        $active = $('.rp-soc-paging a.active').next();
                        if ( $active.length === 0) {
                            $active = $('.rp-soc-paging a:first');
                        }
                    }, 3000); 
                };
                rotateSwitch();
                $(".rp-soc-image_reel a").hover(function() {
                    clearInterval(play); 
                }, function() {rotateSwitch(); });
                $(".rp-soc-paging a").click(function() {
                    $active = $(this); 
                    clearInterval(play);
                    rotate(); 
                    rotateSwitch();
                    return false; 
                });
           });
       </script>
